import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"噬嗑","description":"高岛易断 - 噬嗑","frontmatter":{"title":"噬嗑","description":"高岛易断 - 噬嗑"},"headers":[],"relativePath":"zh/classics/takashima/021.md","filePath":"zh/classics/takashima/021.md"}'),i={name:"zh/classics/takashima/021.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h2 id="噬嗑-1" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑-1" aria-label="Permalink to “噬嗑”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>噬嗑：亨，利用狱。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《杂卦》曰：“噬嗑，食也。”凡食下咽则口合，有物梗之则口不合，不合则不通，合则亨通矣，故曰“噬嗑，亨”。由是而推之，在家庭则有谗邪以梗之，在朝廷则奸佞以梗之，在道路则有强暴以梗之。一如物之在口，有梗则不通也，欲期其通，当先治其梗，治梗者，“利用狱”。治狱宜刚，象取初上两刚，用之者，则在五爻也。“狱”，囚也，外卦《离》体，外实中虚，有狱象焉。内卦《震》，《震》威也，外卦《离》，《离》明也，威而且明，有治狱之才焉，故曰“利”。如是而噬嗑济矣。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>雷电《噬嗑》，先王以明罚敕法。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>《埤雅》曰：电与雷同气，雷从回，电从申，阴阳以回薄而成雷，以申泄而为电，是皆天地之怒气，震发而示威于天下者也，有用刑之象焉。或曰，雷出天气，电出地气，天地气合而雷电作，《噬嗑》即以初上二刚为雷电。先王取其象以治狱，明以象电之光，敕以象雷之震，罚明使民知避，法敕使民知畏，斯罚无枉曲，法无偏私。朝廷之刑罚，一如天延之雷电。天以好生为德，王以恤刑为心，其道一也，其治隆矣。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下正当好运发动，有威仪，有光耀，声名远播上达之象，吉。</p><p>○　问商业：买者卖者，一时会集，有货物旺销之象，吉。</p><p>○　问家宅：天盘地盘皆动，防有火灾，须小心谨慎，可以免祸。</p><p>○　问疾病：是郁热之症，导直透发，或热极作狂，须慎。</p><p>○　问讼事：判决明允。</p><p>○　问天时：有雷雨骤降之象，雨后即霁。</p><p>○　问婚嫁：阴阳一气，定必百年好合，吉。</p><p>○　问行人：即归。</p><p>○　问失物：恐被人吞没。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>《震》为足，初刚居阳在下，象足；初为《震》之下画，亦象屦。“校”刑具，木校也，加校于屦，即加于足也。“灭”没也，以校之小，仅没其趾，罪小而罚轻也。初阳犹微，用刑亦宽，小惩之，使不复为恶而己，故用刑与受刑，两“无咎”也。《象》曰“不行也”，古人制刑，有小罪则校其趾，禁止其行，使不敢复蹈前非，故曰“不行也”。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：目下防有小灾，幸无大患，宜慎。</p><p>○　问商业：木材交易，最为不利，余商亦宜谨慎。</p><p>○　问家宅：有兴工改造之意，无咎。</p><p>○　问疾病：或足患疮疡，或患脚气，症是初发，医治自易。</p><p>○　问战征：防有埋伏，宜慎。</p><p>○　问婚嫁：不利。</p><p>○　问行人：未归。</p><p>○　问六甲：生男。恐小儿有脚疾。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>明治二十三年春，友人某来谓曰：今欲合兴一业，请占成否？筮得《噬嗑》之《晋》。</p><p>断曰：此卦下卦《震》为木，有动性，上卦《离》为火，其象恰如负薪向火，进必陷难，以勿进为宜。今占初爻，曰“屦校灭趾，无咎”，然虽曰“无咎”，不免小惩。《象传》曰“不行也”，明告以事不可行，宜罢而不复为。友人闻之曰：今得此占，愈知其不可为也。余所欲为，本非十全之策，当谢绝同人也。尔后友人又来曰：实三人同谋贷金业，若有以株券及公债证书为抵当借金者，返还之际，一依财主之便宜，予以证书，得借主承诺之证书货金，其所抵当公债证书株券等，连即卖却；又以同一方法贷与其金，次第如此，是不须资本，可得大利。若有请返还者，付以低落之株券等，万一事不如意，则隐匿财产，为破产之策。后奸策发露，二人已下狱。《易》理之妙，实可惊叹！</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“肤”者，柔软无骨之肉，噬之甚易，喻狱之易治；“灭鼻”者，喻得情之深。二爻应五，居中得正，是用刑之得其中正也。刑得中正，则罪人易服，虽“噬肤”而“灭鼻”，“无咎”也。互卦艮为鼻，此爻居艮之初，上有互卦之《坎》，以《艮》陷《坎》下，有灭鼻之象。《象传》曰“乘刚也”，乘初之刚，以济其柔，故噬之，而深没其鼻也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下平平，因才力浅肤，宜乘大力者行事。</p><p>○　问商业：现时货物，有辐辏而合之象，不妨深藏待价，乘时出售。吉。</p><p>○　问战征：“肤”大也，“鼻”始也，从今伊始，可奏肤功，吉。</p><p>○　问家宅：“鼻”为祖，“灭鼻”即灭祖，老宅不利。</p><p>○　问疾病：现下邪在肌肤，致恐深入为患。</p><p>○　问行人：偕伴而归。</p><p>○　问婚嫁：定是兴旺之家，可成。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十五年十月二十五日，杉浦重刚、菊地熊太郎、三宅雄次郎、志贺重昂、陆实诸学士，会于星罔茶寮，前一夕政府有命，停止《日本新闻》发行，时陆氏为该新闻主笔，问余以解停之期，筮得《噬嗑》之《睽》。</p><p>断曰：此卦“颐中有物”之象，噬之粉齑，自得亨也，故曰“噬嗑，亨”。今该新闻纸所载事项，有障害政府，政府停止发行，是其间为事所梗塞也。《噬嗑》之卦，“利用狱”，今六二居下，其罪不重。所谓“噬肤灭鼻”者，如噬美肉，误为热汁伤鼻，象编辑者匆促执笔，触政府之忌讳，被折其鼻也。鼻属金，灭鼻者，为停业而损货财也。下卦为《震》，于数为八，此爻变为《兑》，《兑》数为九，今后八日，或至九日，必可解停。后八日，果解停。陆氏赠书，报知杉浦氏，感其奇中也。</p><p>亲友某来曰：有一商业，为有望之事，请占其成否并吉凶。筮得《噬嗑》之《睽》。</p><p>断曰：此卦口中有物所梗，拟之商业，则为积贮物品之象。占得二爻，是轻易看过商事，反来意外损失。“噬肤”者，谓肉柔而易噬，“灭鼻”者，为逢着刚强，商家致遭折鼻。故宜仔细留心，慎密从事，可无过也，故曰“噬肤灭鼻，无咎”也。后果如此占。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“腊肉”者，肉中藏骨，难噬之物也。骨藏肉中，人所不察，此爻以阴居阳，外柔内刚，有腊肉之象。干肉历久，噬之有肉败生毒，互卦（三、四、五）为《坎》，《坎》者毒之象。肉毒，如罪人强暴，治之而遇反噬，是可吝也。然用刑非为不当，故虽可吝，吝亦小焉，终无咎也。《象传》曰“位不当也”，柔居阳位，不得其当，故罪人不服，而反遇毒也。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：目下气运不正，于得意事中，每多失意，或待人而反受人怨，幸无大害。</p><p>○　问商业：明明可获利之业，或反有小损，多以处置不得其当。</p><p>○　问战征：屯营不得其地，防有小败，宜谨守。</p><p>○　问家宅：宅神不安，恐有小灾，宜祷。</p><p>○　问疾病：药不对病，幸小病无碍。</p><p>○　问行人：因事未归。</p><p>○　问六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人某来，请占刑事裁判，筮得《噬嗑》之《离》。</p><p>断曰：此卦为口中有物，不噬则不通，犹彼我之事，中间被人阻隔，非用力除之，不得调和。今占得六三，曰“噬腊肉，遇毒”，腊肉肉中带骨，坚韧难噬，久则有毒，如犯人刚强难治，久将反噬，未免有“小吝”也。然秉公审断，终得罪状，故曰“无咎”。裁判此案，自当审慎。后果如此占。</p><p>占明治三十年秋丰歉，筮得《噬嗑》之《离》。</p><p>断曰：此卦颐中有物之象，占年成丰凶得此卦，尤见适应也。三爻辞曰“噬腊肉，遇毒”。腊肉者，腌干之小兽肉，体具备，腊时既久，易致生毒，是食物之不洁者也。此卦有雷电交作之象，防七八月间大雨发，损害田谷，秋收不足，谷食缺乏，致人民混食杂粮，或遇毒而致病，谓之“噬腊肉，遇毒”。然今有外国米谷，输入甚便，得以济饥，故曰“小吝，无咎”。是年八月，果气候不顺，洪水遍发，致米谷缺乏，幸输入外国米，藉以济荒。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>“乾胏”，干肉之有骨者也，其坚至矣。坚以象九四之刚；肉柔骨坚，以象九四之阳居阴位。四刚在中，其治狱，必合初上两刚而并治。初刚一画为《乾》，《乾》为金，故初有金象；上刚一画属离，《离》为矢，故上有矢象。四近比五，为治狱之大吏，初上皆从之，故曰“得金矢”。金刚矢直，刚与直，为治狱之要道，九四得之，有何狱之不可治也！故乾胏虽坚韧，不难噬，犹言罪人虽强悍，不患不服矣。在四以柔居刚，刚或过严，故利用艰；柔或过宽，故利用贞，艰且贞，则吉矣。六爻中独四称吉。《象传》曰“未光也”，谓治狱则吉，而四居《离》之初，高明犹微，故曰“未光也”。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：目下改旧从新，正当盛运，万事皆吉。</p><p>○　问商业：譬如食肉得金，有利过于本之象，大吉。</p><p>○　问家宅：家业素丰，安不忘危，常不忘变是保家要道，吉。</p><p>○　问战征：能获敌粮饷，获敌弓矢，无坚不摧，所向皆利。但胜时，更宜谨慎为吉。</p><p>○　问婚嫁：以勤俭之家，吉。</p><p>○　问产生：此症非易治，须谨慎调养，吉。</p><p>○　问六甲：生男。</p><p>○　问行人：在外得利，尚未归也。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>相识某，因商业上生一大纷议，请占其结果如何。筮得《噬嗑》之《颐》。</p><p>断曰：此卦有隔绝被我于中，谋攫大利者，首当用力除去其害。今占得四爻，曰“噬乾胏”，乾胏坚韧难噬，知其人必刚暴难治。曰“得金矢”，金矢贵重之品，想所以争讼者，即在此贵重之金矢也。就金矢取象，金刚象，矢直象，必得一刚直之人，方能判决。然处置甚难，非一时可了，故曰“利艰贞”。始终忍耐，虽多纷议，自然归结，可勿劳心也。后果如此占。</p><h2 id="六五解" tabindex="-1">六五解 <a class="header-anchor" href="#六五解" aria-label="Permalink to “六五解”">​</a></h2><p>“噬乾肉”者，喻肉之无骨易噬。“得黄金”者，黄为正，取正中也；金为刚物，取坚刚也。此爻备刚明之德，尊居五位，即断狱之君也。乾肉为肉已干，狱而至于人君亲决，亦必狱之已成者，罪虽已定，而人君犹有罪疑惟轻之意，故曰“贞厉”。如是而用刑，复何有咎？《象传》曰“得当也”，谓能以柔用刚，守正虑危，治狱之道，得其当也。</p><h2 id="六五占" tabindex="-1">六五占 <a class="header-anchor" href="#六五占" aria-label="Permalink to “六五占”">​</a></h2><p>○　问时运：运正得时，所求所谋，无不如意，吉。</p><p>○　问商业：所贩运货物，皆是上品，干净完美，大得利益；不特一时，此业可保长久。吉。</p><p>○　问家宅：方位得当，大利。</p><p>○　问战征：主敌城柔弱易攻，吉。</p><p>○　问疾病：肉食宣忌，久亦可危，须谨慎调摄。</p><p>○　问行人：正获利归来。</p><p>○　问六甲：生男。</p><p>○　问失物：即得。</p><h2 id="六五案例" tabindex="-1">六五案例 <a class="header-anchor" href="#六五案例" aria-label="Permalink to “六五案例”">​</a></h2><p>占明治二十二年之米作，筮得《噬嗑》之《无妄》。</p><p>断曰：《杂卦传》曰：“噬嗑食也”；《象传》曰：“颐中有物曰噬嗑，噬嗑而亨”，此卦辞皆关食物者也。此卦雷在下，电在上，互卦四爻为七八月，防有洪水。今占得五爻，为丰作之兆也。爻辞曰“噬乾肉”，干肉可藏，新谷登场，纳之仓廪，亦取藏也。曰“得黄金”，稻得黄熟时，称日遍野黄金，米粒称曰金粒、玉粒，盖言丰也。年丰谷熟，贩运者广，米价未必低落，农民既得十分收获，又得高价出卖，亦谓之得黄金也。果至七八月间多雨，二三县虽有被水惨状，全国概得十分丰登，米价颇贵，知《易》理之精妙，不可测度。顷日会某贵显，谈及此占，贵显感叹不措。</p><p>明治二十七年十二月，我海陆军在清国山东省威海卫，清国军舰据要地防御，我军舰在港外，炮击不得其宜。是月二十日，余偶会土方宫内大臣于汽车中，大臣问余以威海卫战况，余筮得《噬嗑》之《无妄》。</p><p>断曰：此卦为“颐中有物”之象，今清兵因过日之败，退守僻地，我海陆兵包围清国海军，犹颐中有物也。今占得五爻，战机正熟，击敌之坚，可有意外之获也，谓之“噬乾肉，得黄金”。虽所行危险，可保无害，谓之“贞厉，无咎”也。后果伊东海军中将，以水雷艇击破铁索，侵入港内，击沉定远等数军舰，敌将丁汝昌以下自杀，镇远等军舰，悉归我有。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上居极位，在五之上，为《离》上画，刚明过盛。“校”，木校，刑具也。初阳在下，故校在足；上阳在上，故校在首。“何校灭耳”，校之厚，知刑之酷也。治狱之道，与其失人，不如失出，宜以钦恤为心。上九刚强自用，重刑示威，安能无凶乎？故曰“凶”。《象传》曰“聪不明也”，谓讼之听，全在于聪，刚而不中，失其聪，即失其明，故曰“聪不明也”。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：目下大运已终，能以柔和处世，可保无虑，若任用强，难免凶矣。</p><p>○　问商业：得利即止，不可过贪，斯无大损。</p><p>○　问家宅：防有意外之灾凶。</p><p>○　问战征：切勿前进，前进必凶。</p><p>○　问疾病：或耳鸣耳聋，或项上生毒，凶。</p><p>○　问六甲：生男，防有聋耳之疾。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>东京曲街酒店主人某，家业上夙操苦心，顷日忽然不理事务。一日午前出家，日暮未归，家人寻之，不得踪迹。时平川町盲人铃木孝伯，尝就余学《易》，家人因请占卜，孝伯筮得《噬嗑》之《震》。</p><p>孝伯断曰：此卦内为《震》雷，外为《离》火，南离方也，趋街之南。雷火发动者，蒸气车也。占得上爻，其辞曰“何校灭耳，凶”，以此推之，恐主人触蒸气车，有灭耳而死之象也。闻者皆惊，或犹未信，既而夜十时，爱宕下警察署急召唤家人，告以主人铁道上横死之事，验之果首耳俱裂。至是皆敬服《易》理之妙。余闻之，喜孝伯判断酷似余言，故附记之。</p><p>明治三十二年四月，某贵绅妻，初有孕，至临月，逾期未产。为占其分娩，用《易》筮，得《噬嗑》之《震》。</p><p>断曰：《噬嗑》之卦，二阳在上下，一阳在三阴之间，即妊娠之象。今占分娩，见有灭耳之辞，是胎儿肥大，难于生产，恐相轧而伤其耳也。后果此妇临褥，久不得产，医师见产妇不堪，将施行截开，渐而分娩。盖因儿肥大，为产门所阻，致耳受伤，因以硝酸银灼之，疗其伤也。儿虽不至“灭耳”，其受伤也确矣。</p>',108)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
